const bin = $input.item.binary || {};
const keys = Object.keys(bin);
let chosen = null;
for (const k of keys) {
  const fn = String(bin[k].fileName || '').toLowerCase();
  if (fn.endsWith('.pdf') || fn.endsWith('.doc') || fn.endsWith('.docx')) { chosen = k; break; }
}
const out = { json: { ...$input.item.json }, binary: {} };
if (chosen) {
  const fn = String(bin[chosen].fileName || '');
  const ext = fn.toLowerCase().split('.').pop();
  out.json.hasResume = true;
  out.json.resumeFileName = fn;
  out.json.resumeExt = ext;
  out.json.isPdf = ext === 'pdf';
  out.binary = { resume: bin[chosen] };
} else {
  out.json.hasResume = false;
  out.json.resumeFileName = '';
  out.json.resumeExt = '';
  out.json.isPdf = false;
}
return out;

const ex = ($input.item.json.output) || {};
let src = {};
try { src = $('Extract & Validate Attachment').item.json; } catch (e) { src = {}; }
const NP = 'Not Provided';
const val = (v) => (v === undefined || v === null || String(v).trim() === '') ? NP : String(v).trim();
const now = new Date().toISOString();
const id = 'CAND-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
return { json: {
  'Candidate ID': id,
  'Name': val(ex.name),
  'Email': val(ex.email),
  'Phone': ex.phone ? "'" + String(ex.phone).trim() : NP,
  'Skills': val(ex.skills),
  'Experience': val(ex.experience),
  'Applied Role': val(ex.appliedRole),
  'Resume Summary': val(ex.summary),
  'Resume File/Link': val(src.resumeFileName),
  'Status': 'Pending',
  'Received Date': now,
  'Processed Date': now,
  'Candidate Status': 'Pending',
  'Last Processed Status': '',
  'Candidate Email Sent': 'No',
  'HR Notification Sent': 'No'
} };

const cand = $('Normalize Candidate Record').first().json;
let rows = [];
try { rows = $('Read Existing Candidates').all().map(i => i.json).filter(r => r && Object.keys(r).length); } catch (e) { rows = []; }
const email = String(cand.Email || '').toLowerCase();
const name = String(cand.Name || '').toLowerCase();
const phone = String(cand.Phone || '').replace(/\D/g, '');
let dup = false;
for (const r of rows) {
  const re = String(r.Email || '').toLowerCase();
  if (email && email !== 'not provided' && re && re === email) { dup = true; break; }
  const rn = String(r.Name || '').toLowerCase();
  const rp = String(r.Phone || '').replace(/\D/g, '');
  if ((!email || email === 'not provided') && name && name !== 'not provided' && rn === name && phone && rp === phone) { dup = true; break; }
}
return [{ json: { ...cand, isDuplicate: dup } }];

const r = $input.item.json;
const status = String(r.Status || '').trim();
const last = String(r['Last Processed Status'] || '').trim();
const allowed = ['Pending', 'Selected', 'On Hold', 'Rejected'];
const valid = allowed.includes(status);
const changed = valid && status !== last;
return { json: { ...r, _status: status, _valid: valid, _changed: changed } };
